    /// <summary>How one value path behaved across calls.</summary>
    private sealed class PathStats
    {
        private const int SeriesKeep = 12, DistinctKeep = 24;
        private int count, changes;
        private string kind, first, last;
        private double min, max, lastNum;
        private bool hasNum, nonDec = true, nonInc = true, overflow;
        private readonly __AxG.List<string> series = new __AxG.List<string>();
        private readonly __AxG.List<string> tail = new __AxG.List<string>();
        private readonly __AxG.List<string> distinctOrder = new __AxG.List<string>();
        private readonly __AxG.Dictionary<string, int> distinct = new __AxG.Dictionary<string, int>();

        internal void Add(Leaf l) { Add(Values.Display(l), l == null ? "absent" : l.Kind, l != null && l.Numeric, l == null ? 0 : l.Number); }

        internal void AddText(string text) { Add(text, "text", false, 0); }

        private void Add(string d, string k, bool numeric, double n)
        {
            count++;
            if (kind == null) kind = k;
            else if (kind != k && kind != "mixed") kind = "mixed";
            if (count > 1 && d != last) changes++;
            if (numeric)
            {
                if (hasNum)
