            if (first == null) first = d;
            last = d;
            if (series.Count < SeriesKeep) series.Add(d);
            tail.Add(d);
            if (tail.Count > 3) tail.RemoveAt(0);
            int seen;
            if (distinct.TryGetValue(d, out seen)) distinct[d] = seen + 1;
            else if (distinct.Count < DistinctKeep) { distinct[d] = 1; distinctOrder.Add(d); }
            else overflow = true;
        }

        internal void Json(__AxS.Text.StringBuilder b)
        {
