            string trend = numeric && changes > 0 ? (nonDec ? "increasing" : nonInc ? "decreasing" : "varying") : (changes > 0 ? "varying" : "constant");
            b.Append("{\"kind\":").Append(global::__AmbioRec.Json.Quote(kind)).Append(",\"count\":").Append(count).Append(",\"changes\":").Append(changes);
            b.Append(",\"distinct\":").Append(overflow ? global::__AmbioRec.Json.Quote(DistinctKeep + "+") : distinct.Count.ToString());
            b.Append(",\"first\":").Append(global::__AmbioRec.Json.Quote(first)).Append(",\"last\":").Append(global::__AmbioRec.Json.Quote(last));
            b.Append(",\"trend\":").Append(global::__AmbioRec.Json.Quote(trend)).Append(",\"series\":").Append(global::__AmbioRec.Json.Strings(series));
            if (numeric && hasNum) b.Append(",\"min\":").Append(global::__AmbioRec.Json.Num(min)).Append(",\"max\":").Append(global::__AmbioRec.Json.Num(max));
            if (count > SeriesKeep) b.Append(",\"tail\":").Append(global::__AmbioRec.Json.Strings(tail));
            if (distinct.Count <= 8 && !overflow)
            {
                __AxG.List<string> top = new __AxG.List<string>(distinctOrder);
                top.Sort(delegate (string x, string y) { return distinct[y].CompareTo(distinct[x]); });
                b.Append(",\"top\":[");
                for (int i = 0; i < top.Count; i++)
                {
                    if (i > 0) b.Append(',');
                    b.Append("{\"value\":").Append(global::__AmbioRec.Json.Quote(top[i])).Append(",\"n\":").Append(distinct[top[i]]).Append('}');
                }
                b.Append(']');
            }
            b.Append('}');
        }
    }

