                        if (a != b && changes.Count < 4)
                        {
                            changes.Add("{\"key\":" + global::__AmbioRec.Json.Quote(k) + ",\"before\":" + global::__AmbioRec.Json.Quote(a) + ",\"after\":" + global::__AmbioRec.Json.Quote(b) + "}");
                        }
                    }
                    if (changes.Count > 0)
                    {
                        Counted d;
                        if (!drift.TryGetValue(node.Path, out d) && drift.Count < 20)
                        {
                            drift[node.Path] = d = new Counted();
                            driftOrder.Add(node.Path);
                        }
                        if (d != null)
                        {
                            d.Calls++;
                            if (d.Examples.Count < 4) d.Examples.Add("{\"fromCall\":" + prev.Call + ",\"toCall\":" + call + ",\"changes\":[" + string.Join(",", changes.ToArray()) + "]}");
                        }
                    }
                }
                Seen now = new Seen();
                now.Call = call;
                now.Fields = node.Fields;
                objects[node.Obj] = now;
            }
        }

        internal void Mutation(string path, string before, string after, int call)
        {
            Counted m;
            if (!mutations.TryGetValue(path, out m))
            {
                if (mutations.Count >= 40) return;
                mutations[path] = m = new Counted();
                mutationOrder.Add(path);
            }
            m.Calls++;
            if (m.Examples.Count < MutationExamples) m.Examples.Add("{\"call\":" + call + ",\"before\":" + global::__AmbioRec.Json.Quote(before) + ",\"after\":" + global::__AmbioRec.Json.Quote(after) + "}");
        }

        internal void Exception(string what)
        {
            errors++;
            int n;
            if (exceptions.TryGetValue(what, out n)) exceptions[what] = n + 1;
            else if (exceptions.Count < MaxExceptions) { exceptions[what] = 1; exceptionOrder.Add(what); }
        }

        /// <summary>Keeps the first calls, the last calls, and the first of each kind of outcome.</summary>
        internal void AddSample(Sample s)
        {
            string shape = s.Threw != null ? "threw:" + s.Threw.Split(':')[0] : Values.OutcomeShape(s.Returned);
            bool known = shapes.Contains(shape);
            if (!known && shapes.Count < 8) shapes.Add(shape);
            if (head.Count < SampleHead) { head.Add(s); return; }
            if (!known && novel.Count < 6) { novel.Add(s); return; }
            tail.Add(s);
            if (tail.Count > SampleTail) tail.RemoveAt(0);
        }

        internal void Json(__AxS.Text.StringBuilder b)
        {
            b.Append("{\"file\":").Append(global::__AmbioRec.Json.Quote(file)).Append(",\"symbol\":").Append(global::__AmbioRec.Json.Quote(symbol));
            b.Append(",\"line\":").Append(line).Append(",\"calls\":").Append(Calls).Append(",\"errors\":").Append(errors);
            b.Append(",\"avgMs\":").Append(global::__AmbioRec.Json.Num(Calls == 0 ? 0 : __AxS.Math.Round(TotalMs / Calls, 3)));
            __AxG.List<Sample> all = new __AxG.List<Sample>(head);
            all.AddRange(novel);
            all.AddRange(tail);
            all.Sort(delegate (Sample x, Sample y) { return x.Call.CompareTo(y.Call); });
            b.Append(",\"samples\":[");
            for (int i = 0; i < all.Count; i++)
            {
                Sample s = all[i];
                if (i > 0) b.Append(',');
                b.Append("{\"call\":").Append(s.Call).Append(",\"args\":").Append(global::__AmbioRec.Json.Quote(s.Args));
                b.Append(",\"ms\":").Append(global::__AmbioRec.Json.Num(__AxS.Math.Round(s.Ms, 3)));
                if (s.Threw != null) b.Append(",\"threw\":").Append(global::__AmbioRec.Json.Quote(s.Threw));
                else b.Append(",\"returned\":").Append(global::__AmbioRec.Json.Quote(s.Returned));
                if (s.Mutated != null) b.Append(",\"mutated\":").Append(global::__AmbioRec.Json.Strings(s.Mutated));
                b.Append('}');
            }
            b.Append("],\"values\":{");
            for (int i = 0; i < pathOrder.Count; i++)
            {
                if (i > 0) b.Append(',');
                b.Append(global::__AmbioRec.Json.Quote(pathOrder[i])).Append(':');
                paths[pathOrder[i]].Json(b);
            }
            b.Append("},\"mutations\":[");
            for (int i = 0; i < mutationOrder.Count; i++)
            {
                Counted m = mutations[mutationOrder[i]];
                if (i > 0) b.Append(',');
                b.Append("{\"path\":").Append(global::__AmbioRec.Json.Quote(mutationOrder[i])).Append(",\"calls\":").Append(m.Calls).Append(",\"examples\":[").Append(string.Join(",", m.Examples.ToArray())).Append("]}");
            }
            b.Append("],\"exceptions\":[");
            for (int i = 0; i < exceptionOrder.Count; i++)
            {
                if (i > 0) b.Append(',');
                b.Append("{\"what\":").Append(global::__AmbioRec.Json.Quote(exceptionOrder[i])).Append(",\"n\":").Append(exceptions[exceptionOrder[i]]).Append('}');
            }
            b.Append("],\"returns\":");
            Returns.Json(b);
            b.Append(",\"shared\":[");
            for (int i = 0; i < sharedOrder.Count; i++)
            {
                Counted st = shared[sharedOrder[i]];
                if (i > 0) b.Append(',');
                b.Append("{\"param\":").Append(global::__AmbioRec.Json.Quote(sharedOrder[i])).Append(",\"calls\":").Append(st.Calls).Append(",\"firstCall\":").Append(st.FirstCall).Append('}');
            }
            b.Append("],\"repeats\":").Append(repeats).Append(",\"repeatExample\":").Append(repeatExample ?? "null").Append(",\"drift\":[");
            for (int i = 0; i < driftOrder.Count; i++)
            {
                Counted d = drift[driftOrder[i]];
                if (i > 0) b.Append(',');
                b.Append("{\"path\":").Append(global::__AmbioRec.Json.Quote(driftOrder[i])).Append(",\"calls\":").Append(d.Calls).Append(",\"examples\":[").Append(string.Join(",", d.Examples.ToArray())).Append("]}");
            }
            b.Append("]}");
        }
    }

    // ── the little JSON the recorder needs ──────────────────────────────────

    private static class Json
    {
        internal static string Quote(string s)
        {
            if (s == null) return "null";
            __AxS.Text.StringBuilder b = new __AxS.Text.StringBuilder(s.Length + 2);
            b.Append('"');
            foreach (char c in s)
            {
                switch (c)
                {
                    case '"': b.Append("\\\""); break;
                    case '\\': b.Append("\\\\"); break;
                    case '\n': b.Append("\\n"); break;
                    case '\r': b.Append("\\r"); break;
                    case '\t': b.Append("\\t"); break;
                    default:
                        if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4"));
                        else b.Append(c);
                        break;
                }
            }
            return b.Append('"').ToString();
        }

        internal static string Num(double d)
        {
            if (double.IsNaN(d) || double.IsInfinity(d)) return "null";
            return d.ToString("R", __AxS.Globalization.CultureInfo.InvariantCulture);
        }

        internal static string Strings(__AxG.List<string> items)
        {
            __AxS.Text.StringBuilder b = new __AxS.Text.StringBuilder("[");
            for (int i = 0; i < items.Count; i++)
            {
                if (i > 0) b.Append(',');
                b.Append(Quote(items[i]));
            }
            return b.Append(']').ToString();
        }

        /// <summary>Parses objects, arrays, strings, numbers, booleans and null; null when malformed.</summary>
        internal static object Parse(string text)
        {
            if (string.IsNullOrEmpty(text)) return null;
            try { int i = 0; return Value(text, ref i); } catch (__AxS.Exception) { return null; }
        }

        private static void Space(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }

        private static object Value(string s, ref int i)
        {
            Space(s, ref i);
            char c = s[i];
            if (c == '{')
            {
                i++;
                __AxG.Dictionary<string, object> map = new __AxG.Dictionary<string, object>();
                Space(s, ref i);
                if (s[i] == '}') { i++; return map; }
                while (true)
                {
                    Space(s, ref i);
                    string k = Text(s, ref i);
                    Space(s, ref i);
                    i++; // :
                    map[k] = Value(s, ref i);
                    Space(s, ref i);
                    if (s[i++] == '}') return map;
                }
            }
            if (c == '[')
            {
                i++;
                __AxG.List<object> list = new __AxG.List<object>();
                Space(s, ref i);
                if (s[i] == ']') { i++; return list; }
                while (true)
                {
                    list.Add(Value(s, ref i));
                    Space(s, ref i);
                    if (s[i++] == ']') return list;
                }
            }
            if (c == '"') return Text(s, ref i);
            if (string.CompareOrdinal(s, i, "true", 0, 4) == 0) { i += 4; return true; }
            if (string.CompareOrdinal(s, i, "false", 0, 5) == 0) { i += 5; return false; }
            if (string.CompareOrdinal(s, i, "null", 0, 4) == 0) { i += 4; return null; }
            int start = i;
            while (i < s.Length && "+-0123456789.eE".IndexOf(s[i]) >= 0) i++;
            return double.Parse(s.Substring(start, i - start), __AxS.Globalization.CultureInfo.InvariantCulture);
        }

        private static string Text(string s, ref int i)
        {
            __AxS.Text.StringBuilder b = new __AxS.Text.StringBuilder();
            i++; // opening quote
            while (true)
            {
                char c = s[i++];
                if (c == '"') return b.ToString();
                if (c != '\\') { b.Append(c); continue; }
                char e = s[i++];
                switch (e)
                {
                    case 'n': b.Append('\n'); break;
                    case 't': b.Append('\t'); break;
                    case 'r': b.Append('\r'); break;
                    case 'b': b.Append('\b'); break;
                    case 'f': b.Append('\f'); break;
                    case 'u': b.Append((char)int.Parse(s.Substring(i, 4), __AxS.Globalization.NumberStyles.HexNumber)); i += 4; break;
                    default: b.Append(e); break;
                }
            }
        }
    }
}
